import type { CartItem } from './types';

/**
 * Encodes the cart state to a URL-friendly string.
 * Format: id1:qty1,id2:qty2
 */
export function encodeCart(items: CartItem[]): string {
  if (!items || items.length === 0) return '';
  return items.map((item) => `${item.id}:${item.qty}`).join(',');
}

/**
 * Decodes the cart state from a URL string.
 * Returns an empty array if the string is empty or invalid.
 */
export function decodeCart(value: unknown): CartItem[] {
  if (typeof value !== 'string' || value.trim() === '') return [];
  const items: CartItem[] = [];
  const parts = value.split(',');
  for (const part of parts) {
    const [idStr, qtyStr] = part.split(':');
    const id = Number(idStr);
    const qty = Number(qtyStr);
    if (Number.isInteger(id) && id > 0 && Number.isInteger(qty) && qty > 0) {
      items.push({ id, qty });
    }
  }
  return items;
}

/**
 * Adds an item to the cart or increments its quantity.
 */
export function addToCart(items: CartItem[], productId: number, qty = 1): CartItem[] {
  const existing = items.find((item) => item.id === productId);
  if (existing) {
    return items.map((item) =>
      item.id === productId ? { ...item, qty: item.qty + qty } : item
    );
  }
  return [...items, { id: productId, qty }];
}

/**
 * Updates the quantity of an item in the cart.
 * Removes the item if quantity becomes 0 or negative.
 */
export function updateCartItemQty(items: CartItem[], productId: number, qty: number): CartItem[] {
  if (qty <= 0) {
    return items.filter((item) => item.id !== productId);
  }
  return items.map((item) =>
    item.id === productId ? { ...item, qty } : item
  );
}

/**
 * Removes an item from the cart.
 */
export function removeFromCart(items: CartItem[], productId: number): CartItem[] {
  return items.filter((item) => item.id !== productId);
}

import { useNavigate } from '@tanstack/react-router';
import type { Product } from '../types';
import type { CartItem } from '../types';
import { removeFromCart, updateCartItemQty } from '../cart';

interface CartProps {
  cart: CartItem[];
  products: Product[];
  onClearCart: () => void;
}

export function Cart({ cart, products, onClearCart }: CartProps) {
  const navigate = useNavigate({ from: '/' });

  // Build a lookup map of products by id for fast access
  const productMap = new Map(products.map((p) => [p.id, p]));

  const itemsWithProducts = cart
    .map((item) => ({
      item,
      product: productMap.get(item.id),
    }))
    .filter((entry): entry is { item: CartItem; product: Product } => Boolean(entry.product));

  const totalItems = cart.reduce((sum, item) => sum + item.qty, 0);
  const subtotal = itemsWithProducts.reduce(
    (sum, { item, product }) => sum + product.price * item.qty,
    0
  );
  const shipping = subtotal > 0 && subtotal < 100 ? 9.99 : 0;
  const tax = subtotal * 0.08;
  const total = subtotal + shipping + tax;

  const handleUpdateQty = (productId: number, delta: number) => {
    const current = cart.find((item) => item.id === productId);
    if (!current) return;
    const newQty = current.qty + delta;
    const next = updateCartItemQty(cart, productId, newQty);
    navigate({
      to: '/',
      search: (prev) => ({
        ...prev,
        cart: next.length > 0
          ? next.map((i) => `${i.id}:${i.qty}`).join(',')
          : undefined,
      }),
      replace: true,
    });
  };

  const handleRemove = (productId: number) => {
    const next = removeFromCart(cart, productId);
    navigate({
      to: '/',
      search: (prev) => ({
        ...prev,
        cart: next.length > 0
          ? next.map((i) => `${i.id}:${i.qty}`).join(',')
          : undefined,
      }),
      replace: true,
    });
  };

  return (
    <aside className="cart-panel">
      <div className="section-title">
        <span>Shopping Cart</span>
        <span style={{ fontSize: 14, fontWeight: 500, color: '#718096' }}>
          {totalItems} {totalItems === 1 ? 'item' : 'items'}
        </span>
      </div>

      {cart.length === 0 ? (
        <div className="cart-empty">
          <div className="cart-empty-icon">🛒</div>
          <p>Your cart is empty</p>
          <p style={{ fontSize: 12, marginTop: 6 }}>
            Add products to get started!
          </p>
        </div>
      ) : (
        <>
          <div className="cart-items">
            {itemsWithProducts.map(({ item, product }) => (
              <div key={product.id} className="cart-item">
                <img
                  className="cart-item-image"
                  src={product.image}
                  alt={product.name}
                  loading="lazy"
                />
                <div className="cart-item-info">
                  <div className="cart-item-name">{product.name}</div>
                  <div className="cart-item-price">
                    ${product.price.toFixed(2)}
                  </div>
                </div>
                <div className="cart-item-controls">
                  <button
                    className="btn btn-icon"
                    onClick={() => handleUpdateQty(product.id, -1)}
                    aria-label={`Decrease quantity of ${product.name}`}
                  >
                    −
                  </button>
                  <span className="cart-item-qty">{item.qty}</span>
                  <button
                    className="btn btn-icon"
                    onClick={() => handleUpdateQty(product.id, 1)}
                    aria-label={`Increase quantity of ${product.name}`}
                  >
                    +
                  </button>
                  <button
                    className="cart-item-remove"
                    onClick={() => handleRemove(product.id)}
                    aria-label={`Remove ${product.name} from cart`}
                    title="Remove from cart"
                  >
                    ×
                  </button>
                </div>
              </div>
            ))}
          </div>

          <div className="cart-summary">
            <div className="cart-summary-row">
              <span>Subtotal</span>
              <span>${subtotal.toFixed(2)}</span>
            </div>
            <div className="cart-summary-row">
              <span>Shipping</span>
              <span>{shipping === 0 ? 'FREE' : `$${shipping.toFixed(2)}`}</span>
            </div>
            <div className="cart-summary-row">
              <span>Tax (8%)</span>
              <span>${tax.toFixed(2)}</span>
            </div>
            <div className="cart-summary-total">
              <span>Total</span>
              <span>${total.toFixed(2)}</span>
            </div>
          </div>

          <div className="cart-actions">
            <button className="btn btn-primary">Checkout</button>
            <button className="btn btn-secondary" onClick={onClearCart}>
              Clear
            </button>
          </div>

          {subtotal < 100 && subtotal > 0 && (
            <div className="url-hint">
              <strong>💡 Free shipping</strong>
              Add ${(100 - subtotal).toFixed(2)} more to qualify for free shipping!
            </div>
          )}
        </>
      )}
    </aside>
  );
}

import { useNavigate } from '@tanstack/react-router';
import type { Product } from '../types';
import type { CartItem } from '../types';
import { addToCart } from '../cart';

interface ProductListProps {
  products: Product[];
  cart: CartItem[];
  isLoading: boolean;
  error: Error | null;
}

export function ProductList({ products, cart, isLoading, error }: ProductListProps) {
  const navigate = useNavigate({ from: '/' });

  const handleAddToCart = (productId: number) => {
    const next = addToCart(cart, productId, 1);
    navigate({
      to: '/',
      search: (prev) => ({
        ...prev,
        cart: next.map((i) => `${i.id}:${i.qty}`).join(','),
      }),
      replace: false,
    });
  };

  if (isLoading) {
    return (
      <div className="loading">
        <p>⏳ Loading products...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="error">
        <p>❌ Error loading products: {error.message}</p>
      </div>
    );
  }

  return (
    <section>
      <div className="section-title">
        <span>Products</span>
        <span style={{ fontSize: 14, fontWeight: 500, color: '#718096' }}>
          {products.length} available
        </span>
      </div>
      <div className="product-list">
        {products.map((product) => {
          const inCart = cart.find((item) => item.id === product.id);
          return (
            <div key={product.id} className="product-card">
              <img
                className="product-image"
                src={product.image}
                alt={product.name}
                loading="lazy"
              />
              <div className="product-info">
                <div className="product-category">{product.category}</div>
                <div className="product-name">{product.name}</div>
                <div className="product-description">{product.description}</div>
                <div className="product-footer">
                  <span className="product-price">
                    ${product.price.toFixed(2)}
                  </span>
                  <button
                    className="btn btn-primary"
                    onClick={() => handleAddToCart(product.id)}
                    aria-label={`Add ${product.name} to cart`}
                  >
                    {inCart ? `Add (${inCart.qty})` : 'Add to Cart'}
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
}

import { useNavigate, useSearch } from '@tanstack/react-router';
import { useQuery } from '@tanstack/react-query';
import { fetchProducts } from './api/products';
import { decodeCart } from './cart';
import { ProductList } from './components/ProductList';
import { Cart } from './components/Cart';

export function App() {
  // Cart state is sourced directly from the URL search params via TanStack Router
  const search = useSearch({ from: '/' });
  const cart = decodeCart(search.cart);

  // Fetch products using TanStack Query
  const {
    data: products = [],
    isLoading,
    error,
  } = useQuery({
    queryKey: ['products'],
    queryFn: fetchProducts,
    staleTime: 5 * 60 * 1000,
  });

  const navigate = useNavigate({ from: '/' });

  const handleClearCart = () => {
    navigate({
      to: '/',
      search: (prev) => ({ ...prev, cart: undefined }),
      replace: true,
    });
  };

  const totalItems = cart.reduce((sum, item) => sum + item.qty, 0);

  return (
    <div className="app">
      <header className="app-header">
        <div>
          <h1>🛍️ TanStack Shop</h1>
          <p>Your cart state is fully stored in the URL — try refreshing!</p>
        </div>
        <div className="cart-summary-badge">
          🛒 {totalItems} {totalItems === 1 ? 'item' : 'items'}
        </div>
      </header>

      <div className="layout">
        <main>
          <ProductList
            products={products}
            cart={cart}
            isLoading={isLoading}
            error={error as Error | null}
          />
        </main>
        <Cart cart={cart} products={products} onClearCart={handleClearCart} />
      </div>
    </div>
  );
}

import { StrictMode } from 'react';
import ReactDOM from 'react-dom/client';
import {
  RouterProvider,
  createRootRoute,
  createRoute,
  createRouter,
  Outlet,
} from '@tanstack/react-router';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { App } from './App';
import './styles.css';

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      refetchOnWindowFocus: false,
      retry: 1,
    },
  },
});

// Root route
const rootRoute = createRootRoute({
  component: () => <Outlet />,
});

// Index route - the main shopping page
// Cart state is stored in the URL search param `cart` (e.g. ?cart=1:2,2:3)
const indexRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/',
  component: App,
  validateSearch: (search: Record<string, unknown>) => {
    // Accept the raw cart string from the URL and forward it to the component.
    // The component decodes it via `decodeCart` so it is robust to malformed input.
    const rawCart = search.cart;
    if (typeof rawCart === 'string' && rawCart.length > 0) {
      return { cart: rawCart };
    }
    // No cart present: use undefined so the param is omitted from the URL.
    return { cart: undefined };
  },
});

// Create the router
const router = createRouter({
  routeTree: rootRoute,
  defaultPreload: 'intent',
});

// Register the router for type-safety
declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router;
  }
}

const rootElement = document.getElementById('root')!;
if (!rootElement.innerHTML) {
  ReactDOM.createRoot(rootElement).render(
    <StrictMode>
      <QueryClientProvider client={queryClient}>
        <RouterProvider router={router} />
      </QueryClientProvider>
    </StrictMode>
  );
